{
  "public_post": "Urgent reminder: All co‑op bread is being recalled due to contaminated flour; please do not consume any loaves and use alternative food until we have safe stock.",
  "coop_message": "We must initiate a full recall of today’s loaves, notify the council immediately, secure a safe flour shipment for tomorrow, and discuss compensation for any residents who fell ill.",
  "reason": "To protect villagers' health, maintain trust, and plan a safe restart of sales."
}

{
  "public_post": "Recall notice: All bread from this week's batch is being recalled; no sales today while we address the contamination.",
  "coop_message": "We need to initiate an immediate recall of all loaves sold this week, inform the council, and source safe flour ASAP; anyone with spare safe flour or contacts for emergency supplies, please share now.",
  "reason": "To stop harm, maintain trust, and coordinate a recall and safe replacement with co‑op members."
}

{
  "public_post": "Attention villagers: No co‑op bread will be sold today; we have secured safe flour and will resume baking tomorrow—please use the farm stand for today.",
  "coop_message": "Team, safe flour arrives tomorrow; meet at 2 pm to finalize the recall, arrange disposal of contaminated loaves, and set up compensation for affected residents before reopening sales.",
  "reason": "Provide an update to villagers and coordinate next steps with co‑op members."
}

{
  "public_post": "Reminder: Do NOT purchase any co‑op bread today; we are recalling all loaves from this week's batch and will have safe bread available tomorrow – please use other food sources in the meantime.",
  "coop_message": "Team, we need to finalize the recall today: arrange collection of all distributed loaves, document affected residents, and confirm the emergency flour shipment arriving tomorrow; meeting at 2 pm to plan compensation and disposal.",
  "reason": "To maintain safety, complete the recall, coordinate logistics, and keep villagers informed."
}

{
  "public_post": "Reminder: No co‑op bread today; the current batch is contaminated. We are arranging a safe replacement and will resume sales tomorrow.",
  "coop_message": "All members, meet at 2 pm to finalize recall paperwork, arrange compensation for affected villagers, and confirm tomorrow's safe flour delivery; please share any contacts for emergency flour.",
  "reason": "To keep villagers safe and coordinate the recall and replacement."
}

{
  "public_post": "Attention villagers: Fresh, safe bread is now available at the co‑op starting today. All contaminated loaves have been recalled and we are offering compensation to anyone who fell ill. Thank you for your patience – come by for fresh bread and refunds.",
  "coop_message": "Team, the recall is now complete and all contaminated loaves have been collected. Prepare refunds and compensation packages for affected residents today. Safe flour is in stock; the bakery will reopen at 8 am. Conduct final quality checks before each batch and coordinate distribution of refunds.",
  "reason": "We are resuming sales with safe flour and need to inform villagers while finalizing recall and compensation."
}

{
  "public_post": "Good news: safe flour has arrived and we have baked a fresh, safe batch of bread. Starting today we are resuming sales; please come to the co‑op for fresh loaves. We apologize for the inconvenience and will provide refunds to anyone affected.",
  "coop_message": "Recall completed: all contaminated loaves collected and disposed. Safe flour delivered; bake and sell today. Prepare refunds for sick villagers and set aside a small stock for tomorrow. Meeting at 2 pm to finalize compensation paperwork.",
  "reason": "We resume sales with safe bread to regain income while ensuring the recall is finished and affected residents are compensated."
}

{
  "public_post": "Attention villagers: Fresh, safe co‑op bread is available today. All refunds for any ill residents have been processed. If you feel unwell, please visit the clinic. Thank you for your patience.",
  "coop_message": "Team, let's ensure no further mixed messages: confirm that safe flour is in stock and sales continue today; finalize any remaining refunds and prepare a brief report for the council on the recall outcome; also discuss a backup flour supplier for future safety.",
  "reason": "To reassure villagers and coordinate final recall tasks while preventing mixed public messages."
}

{
  "public_post": "Good news, villagers: safe flour has arrived and we are back to baking! Fresh, uncontaminated co‑op bread is on sale today (day 5). We apologize for the earlier confusion and will provide refunds to anyone who fell ill.",
  "coop_message": "All members, ensure refunds are processed today and set up sales for day 5. Double‑check quality checks before baking and meet at 2 pm to review inventory and compensation details.",
  "reason": "To correct the mixed messages, resume sales safely, and finalize refunds to maintain trust and income."
}

{
  "public_post": "Good news, villagers: fresh, safe co‑op bread is available today – the recall is complete, refunds have been issued, and we have a limited supply of the new batch. Come by and support the co‑op!",
  "coop_message": "Team, today we have [insert number] loaves ready; aim to sell out while tracking any remaining refund requests. Ensure all sales are recorded and start planning a post‑contamination debrief for tomorrow.",
  "reason": "Encourage sales on the final day while confirming refunds and preparing for next week's operations."
}

{
  "public_post": "Good morning, villagers! Safe, fresh co‑op bread is on sale today. If you were affected by the earlier batch, please come by for a refund or compensation. Thank you for your patience.",
  "coop_message": "Team, ensure all refund paperwork is completed today and that each loaf baked passes the final quality check before sale; also prepare a brief report for the council on our response to the contamination.",
  "reason": "To reassure villagers about safe bread and coordinate final refunds and quality checks."
}

{
  "public_post": "Day 6: Fresh, safe co‑op bread is back on the village board! To thank you for your patience, we’re offering a 20% discount on all loaves today – come by and enjoy our safe, tasty bread again.",
  "coop_message": "All refunds have been processed; please run a final inventory check of today’s stock and confirm we have enough safe flour for tomorrow. Let’s also finalize the backup flour supplier plan discussed on day 5.",
  "reason": "Encourage villagers to buy bread again with a discount while ensuring the co‑op wraps up the recall and secures future safety."
}

{
  "public_post": "Day 6: Fresh, safe co‑op bread is on sale again – all batches now pass extra quality checks, and we’re offering a 10% discount today as a thank‑you for your patience. Come by for your loaf!",
  "coop_message": "Team, excellent work on the recall; today we have 50 loaves ready – aim to sell out while logging each sale, and start drafting the post‑contamination debrief for the council tomorrow.",
  "reason": "Encourage villagers to buy safe bread again and maximize income while completing internal reporting."
}
